content.text:
            }
            return tx.getStream(id);
        }

        void applyNewConnectionId(long sequence, long retirePrior, byte[] cid, byte[] token,
                                  PacketTxn tx, int frameOffset) throws FrameFailure {
            if (tx.peerUndo == null) tx.peerUndo = new PeerCidUndo();
            PeerCidUndo u = tx.peerUndo;
            if (!u.started) { u.started = true; u.oldThreshold = peerCids.threshold; }

            CidRecord existing = peerCids.bySeq.get(sequence);
            if (existing != null) {
                if (!Arrays.equals(existing.cid, cid) || !Arrays.equals(existing.token, token))
                    throw new FrameFailure("PROTOCOL_VIOLATION", frameOffset);
            } else {
                Long owner = peerCids.byCid.get(new ByteKey(cid));
                if (owner != null)
                    throw new FrameFailure("PROTOCOL_VIOLATION", frameOffset);
                CidRecord rec = new CidRecord(sequence, cid, token);
                peerCids.bySeq.put(sequence, rec);
                peerCids.byCid.put(new ByteKey(cid), sequence);
                u.observed.add(sequence);
            }

            if (retirePrior > peerCids.threshold) peerCids.threshold = retirePrior;
            long threshold = peerCids.threshold;
            while (!peerCids.active.isEmpty() && peerCids.active.first() < threshold) {
                long removed = peerCids.active.pollFirst();
                u.activeOps.add(new long[]{2, removed});
            }
            if (sequence >= threshold && peerCids.active.add(sequence))
                u.activeOps.add(new long[]{1, sequence});
            if (peerCids.active.size() > cidLimit)
                throw new FrameFailure("CONNECTION_ID_LIMIT_ERROR", frameOffset);
        }

        // -----------------------------------------------------------------
        // Canonical headers
        // -----------------------------------------------------------------
        int canonicalPnWidth(long pn, long expected) {
            for (int w = 1; w <= 4; w++) {
                long mod = 1L << (8 * w);
                long raw = pn & (mod - 1);
                if (reconstructPn(expected, w, raw) == pn) return w;
            }
            // An accepted PN necessarily had a reconstructing original width.
            return 4;
        }

        void writePn(ByteBuf out, long pn, int width) {
            for (int i = width - 1; i >= 0; i--) out.write((int)(pn >>> (8 * i)));
        }

        byte[] canonicalize(Header h, long pn, long expectedBefore, byte[] payload) {
            int width = canonicalPnWidth(pn, expectedBefore);
            ByteBuf b = new ByteBuf();
            if (h.level == A) {
                b.write(0x40 | ((h.phase & 1) << 2) | (width - 1));
                b.write(h.destination);
                writePn(b, pn, width);
                b.write(payload);
            } else {
                b.write((h.level == I ? 0xc0 : 0xe0) | (width - 1));
                b.write(VERSION);
                b.write(h.destination.length); b.write(h.destination);
                b.write(h.source.length); b.write(h.source);
                if (h.level == I) {
                    writeVarint(b, h.token.length);
                    b.write(h.token);
                }
                writeVarint(b, (long)width + payload.length);
                writePn(b, pn, width);
                b.write(payload);
            }
            return b.bytes();
        }

        // -----------------------------------------------------------------
        // Final state snapshots
        // -----------------------------------------------------------------
        List<long[]> mergeAck(List<long[]> raw) {
            if (raw.isEmpty()) return Collections.emptyList();
            ArrayList<long[]> all = new ArrayList<>(raw);
            all.sort((x, y) -> Long.compare(x[0], y[0]));
            ArrayList<long[]> merged = new ArrayList<>();
            long s = -1, e = -1;
            for (long[] r : all) {
                if (s < 0) { s = r[0]; e = r[1]; }
                else if (r[0] <= e) { if (r[1] > e) e = r[1]; }
                else { merged.add(new long[]{s, e}); s = r[0]; e = r[1]; }
            }
            if (s >= 0) merged.add(new long[]{s, e});
            return merged;
        }

        Map<String,Object> result() {
            Map<String,Object> r = obj();
            ArrayList<Object> pOut = new ArrayList<>();
            for (Map<String,Object> p : packetRows) pOut.add(p);
            r.put("packets", pOut);

            ArrayList<Object> dOut = new ArrayList<>();
            for (Map<String,Object> d : datagramRows) dOut.add(d);
            r.put("datagrams", dOut);

            if (closed == null) r.put("closed", null);
            else r.put("closed", obj("event", closed.event, "packet", closed.packet,
                    "offset", closed.offset, "code", closed.code));

            ArrayList<Object> keyOut = new ArrayList<>();
            for (int i = 0; i < 3; i++) if (keys[i]) keyOut.add(LEVEL_NAME[i]);
            r.put("keys", keyOut);

            r.put("received", obj("I", recv(I), "H", recv(H), "A", recv(A)));
            r.put("key_epoch", keyEpoch);

            ArrayList<Object> epOut = new ArrayList<>();
            for (Map.Entry<Long,EpochStats> e : epochs.entrySet()) {
                EpochStats s = e.getValue();
                if (s.count == 0) continue;
                epOut.add(obj("epoch", e.getKey(), "min", s.min, "max", s.max, "count", s.count));
            }
            r.put("epochs", epOut);

            r.put("opened", obj("bidi", openedBidi, "uni", openedUni));
            r.put("used", used);
            r.put("send_max_data", sendMaxData);
            r.put("send_max_streams", obj("bidi", sendMaxStreams[0], "uni", sendMaxStreams[1]));

            ArrayList<Object> streamOut = new ArrayList<>();
            for (StreamState s : streams.values()) {
                List<long[]> ranges = s.bytes.logicalRanges();
                long prefix = s.bytes.prefix();
                ArrayList<Object> rr = new ArrayList<>();
                for (long[] x : ranges) rr.add(lng(x[0], x[1]));
                streamOut.add(obj("id", s.id, "high", s.high, "final", s.finalSize,
                        "reset", s.reset, "stop", s.stop, "send_max", s.sendMax,
                        "ranges", rr, "unique", s.bytes.unique(), "prefix", prefix,
                        "sha256", shaHex(s.bytes.prefixBytes(prefix))));
            }
            r.put("streams", streamOut);

            ArrayList<Object> cryptoOut = new ArrayList<>();
            for (int i = 0; i < 3; i++) {
                List<long[]> ranges = crypto[i].logicalRanges();
                long prefix = crypto[i].prefix();
                ArrayList<Object> rr = new ArrayList<>();
                for (long[] x : ranges) rr.add(lng(x[0], x[1]));
                cryptoOut.add(obj("level", LEVEL_NAME[i], "ranges", rr,
                        "unique", crypto[i].unique(), "prefix", prefix,
                        "sha256", shaHex(crypto[i].prefixBytes(prefix))));
            }
            r.put("crypto", cryptoOut);

            ArrayList<Object> ackOut = new ArrayList<>();
            for (int i = 0; i < 3; i++) {
                AckState a = ack[i];
                List<long[]> ranges = mergeAck(a.accepted);
                long count = 0;
                for (long[] x : ranges) count += x[1] - x[0];
                long prefix = (!ranges.isEmpty() && ranges.get(0)[0] == 0)
                        ? ranges.get(0)[1] : 0;
                ArrayList<Object> ecn = new ArrayList<>();
                for (long v : a.ecn) ecn.add(v);
                ackOut.add(obj("level", LEVEL_NAME[i], "count", count,
                        "intervals", ranges.size(), "prefix", prefix,
                        "sha256", shaHexIntervalList(ranges), "ecn", ecn));
            }
            r.put("acknowledged", ackOut);

            ArrayList<Object> peerOut = new ArrayList<>();
            for (Long seq : peerCids.active) {
                CidRecord rec = peerCids.bySeq.get(seq);
                peerOut.add(obj("sequence", seq, "id", Main.hex(rec.cid),
                        "token", Main.hex(rec.token)));
            }
            r.put("peer_cids", peerOut);
            r.put("retire_prior_to", peerCids.threshold);

            ArrayList<Object> retOut = new ArrayList<>();
            long rs = -1, re = -1;
            for (Long q : retiredLocal) {
                long x = q;
                if (rs < 0) { rs = x; re = x + 1; }
                else if (x == re) re = x + 1;
                else { retOut.add(lng(rs, re)); rs = x; re = x + 1; }
            }
            if (rs >= 0) retOut.add(lng(rs, re));
            r.put("retired_local", retOut);

            return r;
        }

        Object recv(int level) {
            return receivedLargest[level] < 0 ? null : (Object)receivedLargest[level];
        }
    }
